scenarios:
  - name: '[example] Assign missing defaults'
    code: |
      /* @display
      Value to Process: [
          {name: 'Shirt', price: 10},
          {name: 'Pants'}
      ]
      Default Values: [
              {key: 'price', val: 0},
              {key: 'quantity', val: 1},
              {key: 'currency', val: 'EUR'}
          ]
      @output
      [
          {name: 'Shirt', price: 10, quantity: 1, currency: 'EUR'},
          {name: 'Pants', price: 0, quantity: 1, currency: 'EUR'}
      ]
      */
      const src = [
          {name: 'Shirt', price: 10},
          {name: 'Pants'}
      ];
      const dfs = [
              {key: 'price', val: 0},
              {key: 'quantity', val: 1},
              {key: 'currency', val: 'EUR'}
          ];
      const mockData = {
          src: src,
          dfs: dfs
      };
      let variableResult;
      if (isDirectMode) {
          variableResult = runCode(mockData);
      } else if (isApplyMode) {
          const func = runCode(mockData);
          variableResult = func(src);
      }
      assertThat(variableResult).isEqualTo([
          {name: 'Shirt', price: 10, quantity: 1, currency: 'EUR'},
          {name: 'Pants', price: 0, quantity: 1, currency: 'EUR'}
      ]);
